-- Ṛtam — sthala puranam for the seeded temples
--
-- The traditional origin-legend for each kshetra, kept short and told as
-- tradition rather than asserted as history ("tradition holds…", "the
-- sthala purana relates…"). Only temples whose sthala purana is widely and
-- consistently recorded are filled in here; the rest are deliberately left
-- null for contributors who know the local account to add.

update public.temples set sthala_purana = $$Tradition holds that Venkateswara took residence on the Seven Hills at the close of the Dvapara yuga, and that he borrowed from Kubera to meet the expenses of his marriage to Padmavati. Pilgrims' offerings in the hundi are understood as helping repay that debt, which is why the deity is also called Venkataramana, the lord of the hill.$$ where name = 'Sri Venkateswara Swamy Temple, Tirumala';

update public.temples set sthala_purana = $$Kashi is described as resting on Shiva's trident, standing apart from the earth and untouched by the dissolution of the worlds. The sthala purana relates that Shiva made this his eternal abode, and that those who die here receive the taraka mantra from him at the moment of death.$$ where name = 'Kashi Vishwanath Temple';

update public.temples set sthala_purana = $$The Ramayana account relates that Rama, returning from Lanka, sought to expiate the killing of Ravana, a brahmin, by worshipping Shiva. Hanuman was sent to Kailasa for a lingam; when he was delayed, Sita fashioned one from sand. That lingam, the Ramalingam, is worshipped here, and Hanuman's Vishwalingam is honoured first by Rama's own instruction.$$ where name = 'Ramanathaswamy Temple, Rameswaram';

update public.temples set sthala_purana = $$The image of Krishna here is said to have been given by Rukmini and recovered by Madhvacharya from a ship's cargo of gopichandana, the vessel saved from a storm by his intervention. The deity faces west and is worshipped through a nine-holed window, the Navagraha Kindi, which by tradition was opened for the devotee Kanakadasa, refused entry at the door.$$ where name = 'Sri Krishna Matha, Udupi';

update public.temples set sthala_purana = $$Adi Shankaracharya is said to have chosen this spot on the Tunga after seeing a cobra spread its hood to shade a frog in labour — predator sheltering prey, a sign of the place's sattvic character. He established the southern Amnaya peetham here and installed Sharada, whose mahavakya is Aham Brahmasmi.$$ where name = 'Sringeri Sharada Peetham';

update public.temples set sthala_purana = $$The sthala purana relates that Vitthal came to Pandharpur for his devotee Pundalik, who was serving his aged parents and tossed out a brick for the waiting god to stand upon. Vitthal is still shown standing on that brick, hands on hips, waiting — the posture in which the Warkari tradition knows him.$$ where name = 'Vitthal Rukmini Temple, Pandharpur';

update public.temples set sthala_purana = $$The image is said to have been worshipped by Krishna himself at Dwaraka, and to have been carried at the time of the submersion of that city by Brihaspati (Guru) and Vayu, who installed it here — giving the place its name, Guruvayur.$$ where name = 'Guruvayur Sri Krishna Temple';

update public.temples set sthala_purana = $$One of the Shakti Peethas: when Shiva carried Sati's body across the world in grief, Vishnu's discus severed it, and the parts fell at fifty-one places. The toes of her right foot are said to have fallen here, at the Adi Ganga.$$ where name = 'Kalighat Kali Temple';

update public.temples set sthala_purana = $$First among the Jyotirlingas. The sthala purana relates that Soma (Chandra), cursed by Daksha to waste away, worshipped Shiva at this shore and was released from the curse — recovering, then waning and waxing by turns, which is the origin of the lunar month. The temple has been destroyed and rebuilt many times over the centuries.$$ where name = 'Somnath Temple';

update public.temples set sthala_purana = $$Shiva and Parvati are said to have come to this hill in search of their son Kartikeya, who had withdrawn here in anger after the contest over the divine fruit. They took the forms of Mallikarjuna and Bhramaramba to remain near him. The site is both a Jyotirlinga and a Shakti Peetha.$$ where name = 'Mallikarjuna Jyotirlinga, Srisailam';

update public.temples set sthala_purana = $$The lingam here is svayambhu and faces south, the only Jyotirlinga to do so, which gives it the name Dakshinamukhi. Tradition relates that Shiva emerged from it to destroy the asura Dushana who was persecuting the devotees of Ujjain. The daily Bhasma Aarti, offered with sacred ash before dawn, is unique to this temple.$$ where name = 'Mahakaleshwar Jyotirlinga, Ujjain';

update public.temples set sthala_purana = $$The island in the Narmada is held to be shaped like the syllable Om, from which the kshetra takes its name. The sthala purana relates that Shiva appeared here at the prayer of the Vindhya mountain, and that the lingam divided into two — Omkareshwar and Mamleshwar.$$ where name = 'Omkareshwar Jyotirlinga';

update public.temples set sthala_purana = $$The Pandavas, seeking Shiva to be absolved of the killing of kinsmen at Kurukshetra, followed him to the Himalayas. Shiva took the form of a bull and dived into the ground; the hump remained at Kedarnath, and the other parts appeared at the four shrines of the Panch Kedar.$$ where name = 'Kedarnath Jyotirlinga';

update public.temples set sthala_purana = $$Shiva is said to have taken form here to destroy the asura Tripurasura, and the sweat of that exertion is held to have become the Bhima river, which rises nearby.$$ where name = 'Bhimashankar Jyotirlinga';

update public.temples set sthala_purana = $$The Godavari rises at Brahmagiri above this temple, brought down by the penance of the sage Gautama to absolve him of the death of a cow. The lingam here has three faces — Brahma, Vishnu and Shiva — from which the name Trimbaka comes.$$ where name = 'Trimbakeshwar Jyotirlinga';

update public.temples set sthala_purana = $$Ravana is said to have carried a lingam from Kailasa toward Lanka on the condition that it must not be set down. Tricked into placing it here, he could not lift it again, and it remained — worshipped since as Vaidyanath, the lord of physicians.$$ where name = 'Vaidyanath Jyotirlinga, Deoghar';

update public.temples set sthala_purana = $$Shiva is said to have appeared here to rescue his devotee Supriya, a merchant seized by the asura Daruka, and to have remained as Nageshwar, the lord of serpents.$$ where name = 'Nageshwar Jyotirlinga, Dwarka';

update public.temples set sthala_purana = $$The last of the Jyotirlingas. The sthala purana tells of Ghushma, a devotee who made and immersed a hundred lingams daily; when her son was killed out of jealousy, Shiva restored him from the tank and remained here at her request, taking her name.$$ where name = 'Grishneshwar Jyotirlinga, Ellora';

update public.temples set sthala_purana = $$Tradition relates that Vishnu performed penance here while Lakshmi sheltered him from the Himalayan cold as a badari (jujube) tree, giving the place its name. The shrine is closed through the winter, when the deity is worshipped at Joshimath.$$ where name = 'Badrinath Temple';

update public.temples set sthala_purana = $$Dwaraka is described as the city Krishna built after leaving Mathura, raised from land reclaimed from the sea, and submerged again after his departure from the world. The temple is called Jagat Mandir, and its shrine is entered by the Swarga Dwara and left by the Moksha Dwara.$$ where name = 'Dwarkadhish Temple, Dwarka';

update public.temples set sthala_purana = $$The deities here are carved from neem wood rather than stone, and are replaced in the Nabakalebara rite when a particular conjunction of the calendar occurs. Tradition relates that the sculptor Vishwakarma worked behind closed doors on condition of not being disturbed, and that the forms remained unfinished when the door was opened early — which is why Jagannath, Balabhadra and Subhadra are worshipped in that form.$$ where name = 'Jagannath Temple, Puri';

update public.temples set sthala_purana = $$Among the most important Shakti Peethas, where the yoni of Sati is said to have fallen. There is no image in the sanctum; a cleft in the rock, kept moist by a spring, is worshipped instead. The temple closes for three days during Ambubachi, when the goddess is held to undergo her annual courses.$$ where name = 'Kamakhya Temple';

update public.temples set sthala_purana = $$Kamakshi is said to have worshipped Shiva here as a lingam of sand beneath a mango tree, and to have won him by that penance. Adi Shankaracharya is traditionally associated with the establishment of the Sri Chakra in this sanctum.$$ where name = 'Kamakshi Amman Temple, Kanchipuram';

update public.temples set sthala_purana = $$Meenakshi was born to the Pandya king Malayadhwaja with three breasts, and it was foretold that the third would vanish when she met the one she was to marry — which happened when she encountered Shiva as Sundareswarar. Their marriage, the Thirukalyanam, is re-enacted each year as the temple's great festival.$$ where name = 'Meenakshi Amman Temple, Madurai';

update public.temples set sthala_purana = $$The goddess here is worshipped as Mahalakshmi or Ambabai, and the temple is built so that at certain days in the year the setting sun's rays fall directly on the image — the Kirnotsav.$$ where name = 'Mahalakshmi Temple, Kolhapur';

update public.temples set sthala_purana = $$The sthala purana relates that Shiva drank the halahala poison churned from the ocean and held it in his throat, which turned blue. His consort here is Vishalakshi, and the Ganga passes at the foot of the temple town.$$ where name = 'Vindhyavasini Temple';

update public.temples set sthala_purana = $$An eternal flame burns from the rock here without fuel, worshipped as the goddess herself. Tradition relates that Akbar attempted to extinguish it with a channel of water and failed, and afterwards offered a golden parasol at the shrine.$$ where name = 'Jwalamukhi Temple';

update public.temples set sthala_purana = $$Tradition holds that Shiva took the form of a bull and remained at the foot of this hill, and that the temple was raised at the site by the Chalukya king. The Kaveri encircles the shrine, and the sanctum is kept perpetually damp by a spring — which is why it is counted as the water element among the Pancha Bhoota Sthalams.$$ where name = 'Jambukeswarar Temple, Tiruvanaikaval (Appu Sthalam)';

update public.temples set sthala_purana = $$Parvati is said to have covered Shiva's eyes in play, plunging the worlds into darkness; to expiate it she performed penance here, worshipping a lingam of earth beneath a mango tree, which gives the temple its name and its place as the earth element among the Pancha Bhoota Sthalams.$$ where name = 'Ekambareswarar Temple, Kanchipuram (Prithvi Sthalam)';

update public.temples set sthala_purana = $$Shiva is said to have appeared here as an infinite column of fire when Brahma and Vishnu contended over who was greater, neither able to find its top or base. The hill itself is worshipped as that column, which is why this is the fire element among the Pancha Bhoota Sthalams; the Karthigai Deepam beacon on its summit recalls it.$$ where name = 'Arunachaleswarar Temple, Thiruvannamalai (Agni Sthalam)';

update public.temples set sthala_purana = $$The lamps in the sanctum flicker without any draught, which is why this is counted as the air element among the Pancha Bhoota Sthalams. The temple is associated with Kannappa, the hunter-devotee who offered his own eyes to the lingam, and with the spider, serpent and elephant whose worship gives the place its name.$$ where name = 'Sri Kalahasti Temple (Vayu Sthalam)';

update public.temples set sthala_purana = $$Shiva is worshipped here as Nataraja, performing the Ananda Tandava in the golden hall. The Chidambara Rahasya, behind a curtain beside the image, is empty space — the ether element among the Pancha Bhoota Sthalams, and a teaching that the divine is not confined to form.$$ where name = 'Thillai Nataraja Temple, Chidambaram (Akasha Sthalam)';

update public.temples set sthala_purana = $$Sabarimala is held to be the place where Ayyappa, born of Hari and Hara, meditated after subduing Mahishi. Pilgrims observe a forty-one day vratam before the climb and carry the irumudi on the head.$$ where name = 'Sabarimala Ayyappa Temple';

update public.temples set sthala_purana = $$Vishnu reclines here on Ananta, the serpent, in the yoga-nidra posture, visible through three doors — the head, the torso and the feet. The temple's traditional accounts connect its establishment with the sage Divakara Muni.$$ where name = 'Padmanabhaswamy Temple, Thiruvananthapuram';

update public.temples set sthala_purana = $$Ranganatha reclines here facing south toward Lanka. Tradition relates that Rama gave the image to Vibhishana, who set it down on the Kaveri island while performing his sandhya and found he could not lift it again — so the deity remained, looking toward the kingdom he was to have gone to.$$ where name = 'Ranganathaswamy Temple, Srirangam';

update public.temples set sthala_purana = $$The goddess Bhavatarini is worshipped here, and the temple is inseparable from Sri Ramakrishna Paramahamsa, who served as its priest and had his realisations in its precincts.$$ where name = 'Dakshineswar Kali Temple, Kolkata';
